# Deterministic voucher download, driven straight through Playwright.
#
# The portal's 'download confirmation slip' control does nothing when an agent clicks it
# (three runs: real clicks, no download) and carries no href, so this block goes after the
# file itself rather than asking an agent to click:
#   1. find the control by its text - searching EVERY frame of EVERY open browser tab,
#      because this workflow runs on a persistent browser session whose newest tab is not
#      necessarily the one the previous block left the results table on;
#   2. tag it with a data attribute so it can be clicked by an exact selector;
#   3. wrap window.open / fetch / XMLHttpRequest / createObjectURL so every address its
#      handler asks for - and every Blob it builds - is captured;
#   4. click it (real Playwright click first, scripted click as fallback: either runs the
#      handler, which is all the interception needs);
#   5. hand the browser the FIRST captured Blob or URL whose bytes actually start with
#      %PDF, as an <a download> click.
# A programmatic <a download> click is a genuine browser download, so Skyvern's
# context-level listener saves it into this run's download directory and this block's
# output carries downloaded_file_urls exactly like a file_download block.
#
# Two safeguards learned the hard way: nothing is saved unless the bytes are really a PDF
# (v_5 saved unverified bytes and died in the parser), and a tab is only accepted when the
# booking id is present on it (old tabs from earlier runs on the same persistent session
# would otherwise offer the wrong booking's voucher).

LINK_TEXT = "confirmation slip"
LINK_SELECTOR = "[data-skyvern-voucher-link='1']"
MAX_SCOPES = 8
MAX_CANDIDATES = 8

report = {
    "downloaded_file_urls": [],
    "link_found": False,
    "link_tag": None,
    "link_text": None,
    "link_href": None,
    "link_target": None,
    "link_html": None,
    "link_scope_url": None,
    "booking_id_on_scope": None,
    "scopes_searched": [],
    "page_texts": [],
    "click_route": None,
    "candidate_urls": [],
    "download_result": None,
    "notes": [],
}

find_link_js = """
(args) => {
  const wanted = args[0];
  const bookingId = args[1];
  const norm = (text) => (text || '').replace(/\s+/g, ' ').trim().toLowerCase();
  const body = document.body;
  const pageText = body ? (body.innerText || '') : '';
  const hasBooking = bookingId ? pageText.indexOf(bookingId) !== -1 : true;
  const all = Array.from(document.querySelectorAll('a, button, span, div, td, li, p, i'));
  const matches = all.filter(node => norm(node.textContent).indexOf(wanted) !== -1);
  if (matches.length === 0) return {found: false, url: location.href, hasBooking: hasBooking};
  matches.sort((left, right) => norm(left.textContent).length - norm(right.textContent).length);
  const hit = matches[0];
  hit.setAttribute('data-skyvern-voucher-link', '1');
  const anchor = hit.closest('a');
  return {
    found: true,
    url: location.href,
    hasBooking: hasBooking,
    tag: hit.tagName,
    text: norm(hit.textContent).slice(0, 120),
    href: anchor ? (anchor.href || null) : null,
    target: anchor ? anchor.getAttribute('target') : null,
    html: (hit.outerHTML || '').slice(0, 400)
  };
}
"""

survey_js = """
() => {
  const norm = (text) => (text || '').replace(/\s+/g, ' ').trim();
  const texts = [];
  const nodes = Array.from(document.querySelectorAll('a, button, [role="button"]'));
  for (const node of nodes) {
    const label = norm(node.textContent);
    if (label && label.length < 80 && texts.indexOf(label) === -1) texts.push(label);
    if (texts.length >= 40) break;
  }
  return { url: location.href, title: document.title, texts: texts };
}
"""

install_probe_js = """
() => {
  if (window.skyvernVoucherProbe) return true;
  const probe = { urls: [], blobs: [] };
  window.skyvernVoucherProbe = probe;
  const push = function (value) {
    try { if (value) probe.urls.push(String(value)); } catch (err) {}
  };
  const nativeOpen = window.open;
  window.open = function () { push(arguments[0]); return nativeOpen.apply(this, arguments); };
  const nativeFetch = window.fetch;
  if (nativeFetch) {
    window.fetch = function (input) {
      push(typeof input === 'string' ? input : (input && input.url));
      return nativeFetch.apply(this, arguments);
    };
  }
  const nativeXhrOpen = XMLHttpRequest.prototype.open;
  XMLHttpRequest.prototype.open = function (method, url) {
    push(url);
    return nativeXhrOpen.apply(this, arguments);
  };
  const nativeCreate = URL.createObjectURL;
  URL.createObjectURL = function (obj) {
    const made = nativeCreate.apply(this, arguments);
    push(made);
    try { if (obj && typeof obj.size === 'number') probe.blobs.push(obj); } catch (err) {}
    return made;
  };
  return true;
}
"""

script_click_js = """
() => {
  const hit = document.querySelector('[data-skyvern-voucher-link="1"]');
  if (!hit) return false;
  hit.click();
  return true;
}
"""

read_probe_js = """
() => {
  const probe = window.skyvernVoucherProbe;
  return probe ? probe.urls.slice(-40) : [];
}
"""

save_pdf_js = """
async (urls) => {
  const outcome = { saved: false, source: null, size: 0, attempts: [] };
  const probe = window.skyvernVoucherProbe;
  const looksPdf = async (blob) => {
    if (!blob || blob.size === 0) return false;
    const head = await blob.slice(0, 5).text();
    return head.indexOf('%PDF') === 0;
  };
  const save = (blob) => {
    const objectUrl = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = objectUrl;
    anchor.download = 'voucher.pdf';
    anchor.style.display = 'none';
    document.body.appendChild(anchor);
    anchor.click();
    setTimeout(function () { URL.revokeObjectURL(objectUrl); anchor.remove(); }, 15000);
  };
  const blobs = (probe && probe.blobs) ? probe.blobs : [];
  for (let i = blobs.length - 1; i >= 0; i--) {
    try {
      const blob = blobs[i];
      const good = await looksPdf(blob);
      outcome.attempts.push({ source: 'page-blob', size: blob ? blob.size : 0, pdf: good });
      if (good) { save(blob); outcome.saved = true; outcome.source = 'page-blob'; outcome.size = blob.size; return outcome; }
    } catch (err) {
      outcome.attempts.push({ source: 'page-blob', error: String(err) });
    }
  }
  for (const url of urls) {
    try {
      const res = await fetch(url, { credentials: 'include' });
      const blob = res.ok ? await res.blob() : null;
      const good = res.ok ? await looksPdf(blob) : false;
      outcome.attempts.push({ url: url, status: res.status, size: blob ? blob.size : 0, pdf: good });
      if (good) { save(blob); outcome.saved = true; outcome.source = url; outcome.size = blob.size; return outcome; }
    } catch (err) {
      outcome.attempts.push({ url: url, error: String(err) });
    }
  }
  return outcome;
}
"""

# Every frame of every open tab. get_working_page() hands this block the newest valid page,
# which on a persistent browser session can be a leftover tab rather than the one the
# results table is on - v_6 searched only that page and found no control at all.
scopes = []
seen_scope_urls = []


def add_scope(item):
    if item is None or len(scopes) >= MAX_SCOPES:
        return
    try:
        key = str(item.url)
    except Exception:
        key = ""
    if key and key in seen_scope_urls:
        return
    if key:
        seen_scope_urls.append(key)
    scopes.append(item)


try:
    for frame in page.frames:
        add_scope(frame)
except Exception as exc:
    report["notes"].append("listing frames failed: " + str(exc)[:200])

try:
    for other_page in page.context.pages:
        for frame in other_page.frames:
            add_scope(frame)
except Exception as exc:
    report["notes"].append("listing browser tabs failed: " + str(exc)[:200])

if not scopes:
    scopes.append(page)

target = None
fallback_target = None
fallback_info = None

for scope in scopes:
    info = None
    try:
        info = await scope.evaluate(find_link_js, [LINK_TEXT, str(booking_id)])
    except Exception as exc:
        report["notes"].append("searching a frame failed: " + str(exc)[:150])
        continue
    if not isinstance(info, dict):
        continue
    report["scopes_searched"].append(str(info.get("url"))[:200])
    if not info.get("found"):
        continue
    if info.get("hasBooking"):
        target = scope
        chosen_info = info
        break
    if fallback_target is None:
        fallback_target = scope
        fallback_info = info

if target is None and fallback_target is not None:
    # The control exists but this tab does not show the booking we were asked for. On a
    # persistent browser session that usually means a leftover tab from an earlier run.
    target = fallback_target
    chosen_info = fallback_info
    report["notes"].append(
        "The tab carrying the download control does not show booking " + str(booking_id) +
        "; it may be left over from an earlier run on this browser session."
    )

if target is not None:
    report["link_found"] = True
    report["link_tag"] = chosen_info.get("tag")
    report["link_text"] = chosen_info.get("text")
    report["link_href"] = chosen_info.get("href")
    report["link_target"] = chosen_info.get("target")
    report["link_html"] = chosen_info.get("html")
    report["link_scope_url"] = chosen_info.get("url")
    report["booking_id_on_scope"] = bool(chosen_info.get("hasBooking"))
else:
    report["notes"].append(
        "No control matching '" + LINK_TEXT + "' was found in any frame of any open tab."
    )
    for scope in scopes[:2]:
        survey = None
        try:
            survey = await scope.evaluate(survey_js)
        except Exception:
            continue
        if isinstance(survey, dict) and survey.get("texts"):
            report["page_texts"] = survey.get("texts")
            break

if target is not None:
    try:
        await target.evaluate(install_probe_js)
    except Exception as exc:
        report["notes"].append("installing the request probe failed: " + str(exc)[:200])

    # A real Playwright click first: it is a trusted user gesture, so a handler that opens a
    # window is not treated as a blocked popup. A scripted click still runs the handler,
    # which is all the interception needs, so it is a good enough fallback.
    try:
        await target.click(LINK_SELECTOR, timeout=15000)
        report["click_route"] = "playwright"
    except Exception as exc:
        report["notes"].append("playwright click failed: " + str(exc)[:200])
        try:
            clicked = await target.evaluate(script_click_js)
            report["click_route"] = "script" if clicked else None
        except Exception as inner:
            report["notes"].append("scripted click failed: " + str(inner)[:200])
    await sleep(6)

    seen = None
    try:
        seen = await target.evaluate(read_probe_js)
    except Exception as exc:
        report["notes"].append("reading the request probe failed: " + str(exc)[:200])

    def plausible(url):
        low = url.lower()
        if low.startswith("blob:"):
            return True
        if not (low.startswith("http://") or low.startswith("https://") or low.startswith("/")):
            return False
        for junk in (".js", ".css", ".png", ".jpg", ".jpeg", ".gif", ".svg", ".woff", ".ico", "analytics", "sentry", "hotjar"):
            if junk in low:
                return False
        return True

    def rank(url):
        low = url.lower()
        if low.startswith("blob:"):
            return 0
        for hint in ("pdf", "voucher", "confirm", "slip"):
            if hint in low:
                return 1
        return 2

    collected = []
    href = report["link_href"]
    if isinstance(href, str) and href.strip() and not href.lower().startswith("javascript"):
        collected.append(href)
    if isinstance(seen, list):
        for item in seen:
            text = str(item)
            if text and text not in collected:
                collected.append(text)

    ranked = sorted([url for url in collected if plausible(url)], key=rank)
    report["candidate_urls"] = ranked[:MAX_CANDIDATES]

    try:
        report["download_result"] = await target.evaluate(save_pdf_js, report["candidate_urls"])
    except Exception as exc:
        report["notes"].append("saving the voucher failed: " + str(exc)[:200])
    await sleep(8)

    if isinstance(report["download_result"], dict) and not report["download_result"].get("saved"):
        report["notes"].append(
            "None of the captured addresses returned PDF bytes. See download_result.attempts "
            "for the status and size of each one."
        )

return report

# Stage 1 (portal order row) is authoritative for the fields whose text the
# voucher PDF prints on a single non-wrapping line and therefore truncates:
# hotel name, room type, dates, guest names, IBN, HCN.
# Stage 2 (voucher PDF) supplies the fields the order table never shows:
# address, hotel phone, bed configuration and meal plan.
row_raw = {{ Find_Booking.extracted_information }}
pdf_raw = {{ Extract_Data.extracted_information }}


def unwrap(value):
    if isinstance(value, dict) and "extracted_information" in value:
        value = value["extracted_information"]
    if isinstance(value, list):
        return value[0] if len(value) > 0 else {}
    if isinstance(value, dict):
        return value
    return {}


def text(value):
    if value is None:
        return None
    if not isinstance(value, str):
        value = str(value)
    value = value.strip()
    if not value or value.lower() in ("null", "none", "n/a", "-"):
        return None
    return value


def name_list(value):
    if isinstance(value, str):
        value = value.split(",")
    if not isinstance(value, list):
        return []
    names = []
    for item in value:
        name = text(item)
        if name:
            names.append(name)
    return names


row = unwrap(row_raw)
pdf = unwrap(pdf_raw)

# Guest count is not published anywhere on this portal, so it is derived from
# how many names the order row lists (repeats included: the portal fills one
# name slot per booked guest, often repeating the lead guest's name).
guest_names = name_list(row.get("guestNames"))
adult_count = len(guest_names)
if adult_count == 0:
    reported = row.get("guestCount")
    adult_count = reported if isinstance(reported, int) and reported > 0 else None

hotel_name = text(row.get("hotelName")) or text(pdf.get("voucherHotelName"))

# The voucher repeats the hotel name; surface it separately only when the two
# sources actually disagree, otherwise there is no second name to report.
voucher_hotel_name = text(pdf.get("voucherHotelName"))
supplier_hotel_name = None
if voucher_hotel_name and hotel_name and voucher_hotel_name.lower() != hotel_name.lower():
    supplier_hotel_name = voucher_hotel_name

booking = {
    "hotelName": hotel_name,
    "address": text(pdf.get("address")),
    "checkinDate": text(row.get("checkinDate")),
    "checkoutDate": text(row.get("checkoutDate")),
    "adultCount": adult_count,
    "guestNames": guest_names if guest_names else None,
    "childrenCount": None,
    "supplierHotelName": supplier_hotel_name,
    "roomCategory": text(row.get("roomCategory")) or text(pdf.get("voucherRoomType")),
    "mealPlan": text(pdf.get("mealPlan")),
    "bedType": text(pdf.get("bedType")),
    "phone": text(pdf.get("phone")),
    "ibn": text(row.get("ibn")) or text(pdf.get("voucherBookingNo")),
    "hcn": text(row.get("hcn")) or text(pdf.get("voucherConfirmationNo")),
}

return {"parsed_booking": [booking]}
